def solve():
    N = 2013
    count = 0

    for a1 in range(N):
        for a3 in range(N):
            # Constraint 1: a1 + a3 != 0 (mod 3)
            if (a1 + a3) % 3 == 0:
                continue

            # Constraint 2: If a3 = 0 (mod 11), then a1 != 0 (mod 11)
            if a3 % 11 == 0 and a1 % 11 == 0:
                continue

            # Constraint 3: If a3 = 0 (mod 61), then a1 != 0 (mod 61)
            if a3 % 61 == 0 and a1 % 61 == 0:
                continue

            count += 1

    print(f"Total count T: {count}")

